from __future__ import annotations

"""Lookup of episode metadata, primarily duration.

Durations can change: an episode is sometimes re-published with ads stripped or
re-encoded, making it shorter than a position a client recorded against the old
file. Resume has to stay inside whatever the current duration is.
"""

from resume_models import Episode


class EpisodeCatalog:
    def __init__(self, episodes: list[Episode] | None = None) -> None:
        self._episodes: dict[str, Episode] = {}
        for episode in episodes or []:
            self.add(episode)

    def add(self, episode: Episode) -> Episode:
        self._episodes[episode.episode_id] = episode
        return episode

    def get(self, episode_id: str) -> Episode | None:
        return self._episodes.get(episode_id)

    def require(self, episode_id: str) -> Episode:
        episode = self._episodes.get(episode_id)
        if episode is None:
            raise KeyError(f"unknown episode {episode_id}")
        return episode

    def duration_of(self, episode_id: str) -> int:
        return self.require(episode_id).duration_ms

    def has(self, episode_id: str) -> bool:
        return episode_id in self._episodes

    def episode_ids(self) -> list[str]:
        return list(self._episodes)

    def count(self) -> int:
        return len(self._episodes)


    def durations_map(self) -> dict[str, int]:
        return {eid: ep.duration_ms for eid, ep in self._episodes.items()}

    def total_duration_ms(self) -> int:
        return sum(ep.duration_ms for ep in self._episodes.values())

    def longest_episode_id(self) -> str | None:
        if not self._episodes:
            return None
        return max(self._episodes.values(), key=lambda ep: ep.duration_ms).episode_id

    def remove(self, episode_id: str) -> None:
        self._episodes.pop(episode_id, None)


def build_catalog(specs: list[tuple[str, int]]) -> EpisodeCatalog:
    """Build a catalog from (episode_id, duration_ms) pairs."""

    return EpisodeCatalog([Episode(episode_id=eid, duration_ms=dur) for eid, dur in specs])


def build_catalog_from_raw(raws: list[dict]) -> EpisodeCatalog:
    episodes = [
        Episode(
            episode_id=str(raw["episode_id"]),
            duration_ms=int(raw["duration_ms"]),
            title=str(raw.get("title", "")),
        )
        for raw in raws
    ]
    return EpisodeCatalog(episodes)


def minutes(value: float) -> int:
    """Helper: minutes to milliseconds."""

    return int(value * 60_000)


def seconds(value: float) -> int:
    return int(value * 1_000)

