from __future__ import annotations

"""Top-level resume sync: take a device event, store the right position."""

from episode_catalog import EpisodeCatalog
from position_rules import progress_fraction
from resume_models import EpisodeProgress, ResumeEvent
from resume_reconciler import reconcile
from resume_store import ResumeStore


class PlaybackSync:
    def __init__(self, catalog: EpisodeCatalog, store: ResumeStore | None = None) -> None:
        self._catalog = catalog
        self._store = store if store is not None else ResumeStore()

    @property
    def store(self) -> ResumeStore:
        return self._store

    def sync_resume(self, event: ResumeEvent) -> EpisodeProgress:
        """Reconcile a device's reported position and persist the result."""

        duration_ms = self._catalog.duration_of(event.episode_id)
        current = self._store.get(event.user_id, event.episode_id)
        updated = reconcile(current, event, duration_ms)
        self._store.save(updated)
        return updated

    def sync_many(self, events: list[ResumeEvent]) -> EpisodeProgress | None:
        result: EpisodeProgress | None = None
        for event in events:
            result = self.sync_resume(event)
        return result

    def resume_position(self, user_id: str, episode_id: str) -> int | None:
        return self._store.position_of(user_id, episode_id)

    def progress(self, user_id: str, episode_id: str) -> float:
        row = self._store.get(user_id, episode_id)
        if row is None:
            return 0.0
        duration = self._catalog.duration_of(episode_id)
        return progress_fraction(row.position_ms, duration)

    def summarize(self, user_id: str, episode_id: str) -> dict[str, object]:
        row = self._store.get(user_id, episode_id)
        if row is None:
            return {"exists": False}
        return {
            "exists": True,
            "position_ms": row.position_ms,
            "recorded_at": row.recorded_at,
            "device_id": row.device_id,
            "update_count": row.update_count,
            "progress": self.progress(user_id, episode_id),
        }

    def has_progress(self, user_id: str, episode_id: str) -> bool:
        return self._store.has(user_id, episode_id)

    def in_progress_episodes(self, user_id: str) -> list[str]:
        return self._store.episodes_for_user(user_id)

    def positions(self, user_id: str) -> dict[str, int]:
        return self._store.positions_map(user_id)

    def reset(self, user_id: str, episode_id: str) -> None:
        self._store.delete(user_id, episode_id)

    def is_complete(self, user_id: str, episode_id: str) -> bool:
        from position_rules import is_complete

        row = self._store.get(user_id, episode_id)
        if row is None:
            return False
        return is_complete(row.position_ms, self._catalog.duration_of(episode_id))

    def continue_listening(self, user_id: str) -> list[str]:
        """Episodes in progress that the user has not finished."""

        return [
            episode_id
            for episode_id in self._store.episodes_for_user(user_id)
            if not self.is_complete(user_id, episode_id)
        ]

