from __future__ import annotations

"""Rules for a playback position relative to an episode's duration.

A stored resume position must always be a real point inside the episode: not
negative, and not past the end (which can happen when the episode was
re-encoded shorter than the file a client played against).
"""

NEAR_END_MS = 15_000


def clamp_position(position_ms: int, duration_ms: int) -> int:
    """Pin a position into the valid range for an episode."""

    return position_ms


def progress_fraction(position_ms: int, duration_ms: int) -> float:
    if duration_ms <= 0:
        return 0.0
    return clamp_position(position_ms, duration_ms) / duration_ms


def remaining_ms(position_ms: int, duration_ms: int) -> int:
    return max(0, duration_ms - clamp_position(position_ms, duration_ms))


def is_near_end(position_ms: int, duration_ms: int, threshold_ms: int = NEAR_END_MS) -> bool:
    return remaining_ms(position_ms, duration_ms) <= threshold_ms


def is_complete(position_ms: int, duration_ms: int, threshold_ms: int = NEAR_END_MS) -> bool:
    return clamp_position(position_ms, duration_ms) >= duration_ms - threshold_ms


def format_position(position_ms: int) -> str:
    total_seconds = max(0, position_ms) // 1000
    minutes, seconds = divmod(total_seconds, 60)
    return f"{minutes}:{seconds:02d}"


def clamp_to_episode(position_ms: int, episode) -> int:
    """Clamp using an Episode object rather than a raw duration."""

    return clamp_position(position_ms, episode.duration_ms)


def percent_complete(position_ms: int, duration_ms: int) -> int:
    return round(progress_fraction(position_ms, duration_ms) * 100)


def time_remaining_label(position_ms: int, duration_ms: int) -> str:
    return f"-{format_position(remaining_ms(position_ms, duration_ms))}"


def is_started(position_ms: int, duration_ms: int, threshold_ms: int = 1000) -> bool:
    return clamp_position(position_ms, duration_ms) >= threshold_ms


def position_label(position_ms: int, duration_ms: int) -> str:
    return f"{format_position(clamp_position(position_ms, duration_ms))} / {format_position(duration_ms)}"


def describe_position(position_ms: int, duration_ms: int) -> dict[str, object]:
    return {
        "position_ms": clamp_position(position_ms, duration_ms),
        "percent": percent_complete(position_ms, duration_ms),
        "remaining_ms": remaining_ms(position_ms, duration_ms),
        "near_end": is_near_end(position_ms, duration_ms),
    }


def format_duration(duration_ms: int) -> str:
    return format_position(duration_ms)


def elapsed_label(position_ms: int, duration_ms: int) -> str:
    return f"+{format_position(clamp_position(position_ms, duration_ms))}"


def within_bounds(position_ms: int, duration_ms: int) -> bool:
    """Whether a raw position already sits inside the episode."""

    return 0 <= position_ms <= duration_ms

