from __future__ import annotations

"""Models for cross-device episode resume.

Each device reports where the listener paused as a ``ResumeEvent`` carrying a
``position_ms`` and the time that listening actually happened (``recorded_at``,
epoch milliseconds). Events do not necessarily arrive in the order they were
recorded — a tablet that was offline can deliver an old position after the phone
already moved ahead. The stored ``EpisodeProgress`` is what every device reads
back to resume.
"""

from dataclasses import dataclass


@dataclass(frozen=True)
class Episode:
    episode_id: str
    duration_ms: int
    title: str = ""

    def __post_init__(self) -> None:
        if not self.episode_id.strip():
            raise ValueError("episode_id is required")
        if self.duration_ms <= 0:
            raise ValueError("duration_ms must be positive")


@dataclass(frozen=True)
class ResumeEvent:
    episode_id: str
    user_id: str
    position_ms: int
    recorded_at: int
    device_id: str

    def __post_init__(self) -> None:
        if not self.episode_id.strip():
            raise ValueError("episode_id is required")
        if not self.user_id.strip():
            raise ValueError("user_id is required")
        if self.recorded_at < 0:
            raise ValueError("recorded_at must be non-negative")
        if not self.device_id.strip():
            raise ValueError("device_id is required")

    @classmethod
    def from_raw(cls, raw: dict) -> "ResumeEvent":
        return cls(
            episode_id=str(raw.get("episode_id", "")),
            user_id=str(raw.get("user_id", "")),
            position_ms=int(raw.get("position_ms", 0)),
            recorded_at=int(raw.get("recorded_at", 0)),
            device_id=str(raw.get("device_id", "")),
        )


@dataclass(frozen=True)
class EpisodeProgress:
    episode_id: str
    user_id: str
    position_ms: int
    recorded_at: int
    device_id: str
    update_count: int = 1

    def key(self) -> tuple[str, str]:
        return (self.user_id, self.episode_id)


def build_event(
    episode_id: str,
    user_id: str,
    position_ms: int,
    recorded_at: int,
    device_id: str = "device-1",
) -> ResumeEvent:
    return ResumeEvent(
        episode_id=episode_id,
        user_id=user_id,
        position_ms=position_ms,
        recorded_at=recorded_at,
        device_id=device_id,
    )

