from __future__ import annotations

"""Decide the resulting resume position when an event meets the stored one."""

from position_rules import clamp_position
from resume_models import EpisodeProgress, ResumeEvent


def reconcile(
    current: EpisodeProgress | None,
    event: ResumeEvent,
    duration_ms: int,
) -> EpisodeProgress:
    """Fold a resume event into the stored progress for its episode."""

    position = clamp_position(event.position_ms, duration_ms)

    if current is None:
        return EpisodeProgress(
            episode_id=event.episode_id,
            user_id=event.user_id,
            position_ms=position,
            recorded_at=event.recorded_at,
            device_id=event.device_id,
            update_count=1,
        )

    return EpisodeProgress(
        episode_id=event.episode_id,
        user_id=event.user_id,
        position_ms=position,
        recorded_at=event.recorded_at,
        device_id=event.device_id,
        update_count=current.update_count + 1,
    )


def is_newer(event: ResumeEvent, current: EpisodeProgress | None) -> bool:
    if current is None:
        return True
    return event.recorded_at > current.recorded_at


def describe_reconcile(current: EpisodeProgress | None, event: ResumeEvent) -> str:
    if current is None:
        return f"first position for {event.episode_id} at {event.position_ms}ms"
    if is_newer(event, current):
        return f"advance {current.position_ms}ms -> {event.position_ms}ms"
    return f"ignore stale {event.position_ms}ms (kept {current.position_ms}ms)"


def reconcile_events(
    events: list[ResumeEvent],
    duration_ms: int,
    current: EpisodeProgress | None = None,
) -> EpisodeProgress | None:
    """Fold a sequence of events into a single progress, in arrival order."""

    for event in events:
        current = reconcile(current, event, duration_ms)
    return current


def applied_position(
    current: EpisodeProgress | None,
    event: ResumeEvent,
    duration_ms: int,
) -> int:
    return reconcile(current, event, duration_ms).position_ms


def latest_recorded_at(events: list[ResumeEvent]) -> int | None:
    """The greatest recorded_at among events (None if empty)."""

    return max((e.recorded_at for e in events), default=None)


def stale_event_count(events: list[ResumeEvent]) -> int:
    """How many events are older than a later one already seen in the list."""

    seen_max = -1
    stale = 0
    for event in events:
        if event.recorded_at <= seen_max:
            stale += 1
        else:
            seen_max = event.recorded_at
    return stale

