import pytest

from episode_catalog import build_catalog, minutes
from resume_models import build_event
from position_rules import clamp_position, format_position, progress_fraction
from resume_reconciler import is_newer, reconcile
from playback_sync import PlaybackSync


def catalog():
    return build_catalog([("ep1", minutes(30)), ("ep2", minutes(10))])


def sync():
    return PlaybackSync(catalog())


def ev(position_ms, recorded_at, device="phone", episode="ep1", user="u"):
    return build_event(episode, user, position_ms, recorded_at, device)


# --- bug B: clamping to episode duration ---

def test_clamp_within_range_is_unchanged():
    assert clamp_position(minutes(5), minutes(30)) == minutes(5)


def test_clamp_beyond_duration():
    assert clamp_position(minutes(40), minutes(30)) == minutes(30)


def test_clamp_negative_position_to_zero():
    assert clamp_position(-5000, minutes(30)) == 0


def test_clamp_at_exact_duration_boundary():
    assert clamp_position(minutes(30), minutes(30)) == minutes(30)


def test_sync_clamps_position_past_reencoded_duration():
    s = sync()
    # ep2 is 10 minutes; a client recorded 12 minutes against an older, longer file.
    s.sync_resume(ev(minutes(12), recorded_at=1000, episode="ep2"))
    assert s.resume_position("u", "ep2") == minutes(10)


def test_progress_never_exceeds_one():
    assert progress_fraction(minutes(45), minutes(30)) == 1.0


# --- bug A: recency-based conflict resolution ---

def test_first_event_is_accepted():
    s = sync()
    s.sync_resume(ev(minutes(5), recorded_at=1000))
    assert s.resume_position("u", "ep1") == minutes(5)


def test_newer_event_advances_position():
    s = sync()
    s.sync_resume(ev(minutes(5), recorded_at=1000))
    s.sync_resume(ev(minutes(10), recorded_at=2000))
    assert s.resume_position("u", "ep1") == minutes(10)


def test_stale_device_write_does_not_regress():
    s = sync()
    s.sync_resume(ev(minutes(20), recorded_at=2000, device="phone"))
    s.sync_resume(ev(minutes(3), recorded_at=1000, device="tablet"))
    assert s.resume_position("u", "ep1") == minutes(20)
    assert s.summarize("u", "ep1")["device_id"] == "phone"


def test_equal_recorded_at_keeps_current():
    s = sync()
    s.sync_resume(ev(minutes(20), recorded_at=2000, device="phone"))
    s.sync_resume(ev(minutes(1), recorded_at=2000, device="tablet"))
    assert s.resume_position("u", "ep1") == minutes(20)


def test_out_of_order_arrivals_keep_latest_recorded():
    s = sync()
    s.sync_many([
        ev(minutes(25), recorded_at=3000),
        ev(minutes(5), recorded_at=1000),
        ev(minutes(15), recorded_at=2000),
    ])
    assert s.resume_position("u", "ep1") == minutes(25)


def test_stale_event_does_not_increment_update_count():
    s = sync()
    s.sync_resume(ev(minutes(20), recorded_at=2000))
    s.sync_resume(ev(minutes(3), recorded_at=1000))
    assert s.summarize("u", "ep1")["update_count"] == 1


# --- helpers / orchestration ---

def test_is_newer_helper():
    s = sync()
    first = s.sync_resume(ev(minutes(10), recorded_at=2000))
    assert is_newer(ev(minutes(11), recorded_at=2500), first) is True
    assert is_newer(ev(minutes(1), recorded_at=1500), first) is False


def test_reconcile_first_event_without_current():
    progress = reconcile(None, ev(minutes(8), recorded_at=1000), minutes(30))
    assert progress.position_ms == minutes(8)
    assert progress.update_count == 1


def test_format_position_mm_ss():
    assert format_position(minutes(3) + 5000) == "3:05"


def test_unknown_episode_raises():
    with pytest.raises(KeyError):
        sync().sync_resume(ev(minutes(5), recorded_at=1000, episode="missing"))


def test_summary_for_unknown_progress():
    assert sync().summarize("u", "ep1") == {"exists": False}
